import Foundation
import Vapor

// MARK: - Circuit Breaker Pattern
enum CircuitState {
    case closed
    case open
    case halfOpen
}

class CircuitBreaker {
    private var state: CircuitState = .closed
    private var failureCount: Int = 0
    private var lastFailureTime: Date?
    private let failureThreshold: Int = 5
    private let recoveryTimeout: TimeInterval = 30
    private let lock = NSLock()

    func execute<T>(_ operation: () throws -> T) throws -> T {
        lock.lock()
        defer { lock.unlock() }

        switch state {
        case .open:
            if let lastFailure = lastFailureTime,
               Date().timeIntervalSince(lastFailure) > recoveryTimeout {
                state = .halfOpen
            } else {
                throw CircuitBreakerError.circuitOpen
            }
        case .halfOpen, .closed:
            break
        }

        do {
            let result = try operation()
            if state == .halfOpen {
                state = .closed
                failureCount = 0
            }
            return result
        } catch {
            failureCount += 1
            lastFailureTime = Date()
            if failureCount >= failureThreshold {
                state = .open
            }
            throw error
        }
    }
}

enum CircuitBreakerError: Error {
    case circuitOpen
}

// MARK: - NTLM Authentication Handler
struct NTLMAuthConfig {
    let domainController: String
    let servicePrincipal: String
    let requireChannelBinding: Bool
    let requireMessageIntegrity: Bool
    let allowedAuthSchemes: [String]
}

class NTLMRelayProtection {
    private let config: NTLMAuthConfig
    private let circuitBreaker: CircuitBreaker
    private var activeNegotiations: [String: NTLMNegotiationState] = [:]
    private let negotiationLock = NSLock()

    init(config: NTLMAuthConfig) {
        self.config = config
        self.circuitBreaker = CircuitBreaker()
    }

    struct NTLMNegotiationState {
        let serverChallenge: Data
        let timestamp: Date
        let clientAddress: String
        let targetInfo: Data
        var channelBindingToken: Data?
    }

    func validateType3Message(
        _ type3Data: Data,
        negotiationId: String,
        requestEPA: Data?,
        sourceIP: String
    ) throws -> Bool {
        return try circuitBreaker.execute {
            negotiationLock.lock()
            guard let state = activeNegotiations[negotiationId] else {
                negotiationLock.unlock()
                throw AuthError.invalidNegotiation
            }
            negotiationLock.unlock()

            // Verify source IP matches original negotiation
            guard state.clientAddress == sourceIP else {
                throw AuthError.addressMismatch
            }

            // Check negotiation timeout (60 seconds)
            guard Date().timeIntervalSince(state.timestamp) < 60 else {
                throw AuthError.negotiationExpired
            }

            // Parse NTLMv2 response from Type 3 message
            let ntlmResponse = try parseNTLMv2Response(type3Data)

            // Validate MIC (Message Integrity Code)
            if config.requireMessageIntegrity {
                guard let mic = ntlmResponse.mic else {
                    throw AuthError.missingMIC
                }
                guard validateMIC(mic, type3Data: type3Data, state: state) else {
                    throw AuthError.invalidMIC
                }
            }

            // Channel Binding validation - EPA (Extended Protection for Authentication)
            if config.requireChannelBinding {
                guard let epaToken = requestEPA else {
                    throw AuthError.missingChannelBinding
                }
                // Critical: validate channel binding from AV_PAIR in NTLMv2 response
                let cbValid = validateChannelBinding(
                    avPairs: ntlmResponse.avPairs,
                    expectedBinding: epaToken,
                    negotiationState: state
                )
                guard cbValid else {
                    throw AuthError.channelBindingMismatch
                }
            }

            return true
        }
    }

    private func validateChannelBinding(
        avPairs: [AVPair],
        expectedBinding: Data,
        negotiationState: NTLMNegotiationState
    ) -> Bool {
        // Find MsvAvChannelBindings in AV_PAIR list
        guard let cbPair = avPairs.first(where: { $0.id == AVPairID.msvAvChannelBindings }) else {
            return false
        }

        // Compare the MD5 hash of the channel binding token
        // NOTE: We compare what the CLIENT claims vs what we expect from TLS session
        let clientCBHash = cbPair.value
        let expectedCBHash = computeMD5(expectedBinding)

        // Timing-safe comparison to prevent side-channel
        return constantTimeCompare(clientCBHash, expectedCBHash)
    }

    private func validateMIC(_ mic: Data, type3Data: Data, state: NTLMNegotiationState) -> Bool {
        // MIC validation: HMAC-MD5 over concatenation of all three messages
        // In relay scenario, attacker cannot forge MIC without session key
        let expectedMIC = computeExpectedMIC(type3Data: type3Data, challenge: state.serverChallenge)
        return constantTimeCompare(mic, expectedMIC)
    }

    func initiateNegotiation(clientIP: String, tlsChannelBinding: Data?) -> (String, Data) {
        let challenge = generateSecureRandom(length: 8)
        let negotiationId = UUID().uuidString
        let targetInfo = buildTargetInfo()

        let state = NTLMNegotiationState(
            serverChallenge: challenge,
            timestamp: Date(),
            clientAddress: clientIP,
            targetInfo: targetInfo,
            channelBindingToken: tlsChannelBinding
        )

        negotiationLock.lock()
        activeNegotiations[negotiationId] = state
        negotiationLock.unlock()

        return (negotiationId, challenge)
    }

    // MARK: - Configuration factory
    static func createDefault(domainController: String) -> NTLMRelayProtection {
        let config = NTLMAuthConfig(
            domainController: domainController,
            servicePrincipal: "HTTP/api.internal",
            requireChannelBinding: true,
            requireMessageIntegrity: true,
            allowedAuthSchemes: ["NTLMv2"]
        )
        return NTLMRelayProtection(config: config)
    }

    // MARK: - Route handler integration
    func authMiddleware(req: Request) throws -> Response {
        let authHeader = req.headers.first(name: .authorization) ?? ""
        let sourceIP = req.remoteAddress?.ipAddress ?? "unknown"

        if authHeader.hasPrefix("NTLM ") {
            let tokenData = Data(base64Encoded: String(authHeader.dropFirst(5))) ?? Data()
            let messageType = detectNTLMMessageType(tokenData)

            switch messageType {
            case 1:
                let tlsBinding = extractTLSChannelBinding(req: req)
                let (negId, challenge) = initiateNegotiation(
                    clientIP: sourceIP,
                    tlsChannelBinding: tlsBinding
                )
                let type2 = buildType2Message(challenge: challenge, negotiationId: negId)
                return Response(status: .unauthorized, headers: [
                    "WWW-Authenticate": "NTLM \(type2.base64EncodedString())"
                ])
            case 3:
                let negId = req.headers.first(name: "X-Negotiation-Id") ?? ""
                let epa = extractTLSChannelBinding(req: req)
                let valid = try validateType3Message(
                    tokenData,
                    negotiationId: negId,
                    requestEPA: epa,
                    sourceIP: sourceIP
                )
                if valid {
                    return Response(status: .ok)
                }
            default:
                break
            }
        }
        return Response(status: .unauthorized)
    }
}

